import 'package:flutter_test/flutter_test.dart'; import 'package:eye_control/platform/eye_control_platform.dart'; import 'package:eye_control/presentation/providers/calibration_provider.dart'; class FakePlatform extends EyeControlPlatform{bool value=true;@override Future<bool> isCalibrationReady()async=>value;@override Future<void> clearCalibration()async{value=false;}} void main(){test('refreshes and clears calibration',()async{final f=FakePlatform();final p=CalibrationProvider(platform:f);await p.refresh();expect(p.ready,isTrue);await p.clear();expect(p.ready,isFalse);});}